/**
 * Compute the byte stride for a struct descriptor map.
 *
 * @param {Object<string, Object>} descriptors - Field descriptor map.
 * @returns {number} Byte size of the struct (aligned).
 */
export function structSize(descriptors: {
    [x: string]: any;
}): number;
/**
 * Compute the maximum alignment requirement for a struct descriptor map.
 *
 * @param {Object<string, Object>} descriptors - Field descriptor map.
 * @returns {number} Byte alignment.
 */
export function structAlign(descriptors: {
    [x: string]: any;
}): number;
/**
 * Create an array-like view of buffer-backed objects.
 *
 * @param {SharedArrayBuffer|ArrayBuffer} buffer - Backing buffer.
 * @param {Object<string, Object>} descriptors - Field descriptor map.
 * @param {Object} [options] - View options.
 * @param {number} [options.byteOffset=0] - Byte offset into the buffer.
 * @param {number} [options.length=0] - Number of items (0 = infer).
 * @param {number} [options.align] - Alignment override.
 * @returns {Object[]} Proxy-backed array of objects.
 *
 * @example
 * ```js
 * const schema = { x: Float32(), y: Float32() };
 * const buffer = new SharedArrayBuffer( structSize( schema ) * 8 );
 * const items = ArrayOfBufferBackedObjects( buffer, schema );
 * items[ 0 ].x = 1;
 * items[ 0 ].y = 2;
 * ```
 */
export function ArrayOfBufferBackedObjects(buffer: SharedArrayBuffer | ArrayBuffer, descriptors: {
    [x: string]: any;
}, { byteOffset, length, align }?: {
    byteOffset?: number;
    length?: number;
    align?: number;
}): any[];
/**
 * Create a single buffer-backed object view.
 *
 * @param {SharedArrayBuffer|ArrayBuffer} buffer - Backing buffer.
 * @param {Object<string, Object>} descriptors - Field descriptor map.
 * @param {Object} [options] - View options.
 * @param {number} [options.byteOffset=0] - Byte offset into the buffer.
 * @param {number} [options.align=1] - Alignment override.
 * @returns {Object} Buffer-backed object view.
 */
export function BufferBackedObject(buffer: SharedArrayBuffer | ArrayBuffer, descriptors: {
    [x: string]: any;
}, { byteOffset, align }?: {
    byteOffset?: number;
    align?: number;
}): any;
/**
 * Descriptor for an unsigned 16-bit integer field.
 *
 * @param {Object} [options]
 * @param {'little'|'big'} [options.endianness='little'] - Byte order.
 * @param {number} [options.align=2] - Alignment in bytes.
 * @returns {Object} Field descriptor.
 */
export function Uint16({ endianness, align }?: {
    endianness?: "little" | "big";
    align?: number;
}): any;
/**
 * Descriptor for an unsigned 32-bit integer field.
 *
 * @param {Object} [options]
 * @param {'little'|'big'} [options.endianness='little'] - Byte order.
 * @param {number} [options.align=4] - Alignment in bytes.
 * @returns {Object} Field descriptor.
 */
export function Uint32({ endianness, align }?: {
    endianness?: "little" | "big";
    align?: number;
}): any;
/**
 * Descriptor for a signed 16-bit integer field.
 *
 * @param {Object} [options]
 * @param {'little'|'big'} [options.endianness='little'] - Byte order.
 * @param {number} [options.align=2] - Alignment in bytes.
 * @returns {Object} Field descriptor.
 */
export function Int16({ endianness, align }?: {
    endianness?: "little" | "big";
    align?: number;
}): any;
/**
 * Descriptor for a signed 32-bit integer field.
 *
 * @param {Object} [options]
 * @param {'little'|'big'} [options.endianness='little'] - Byte order.
 * @param {number} [options.align=4] - Alignment in bytes.
 * @returns {Object} Field descriptor.
 */
export function Int32({ endianness, align }?: {
    endianness?: "little" | "big";
    align?: number;
}): any;
/**
 * Descriptor for a 32-bit float field.
 *
 * @param {Object} [options]
 * @param {'little'|'big'} [options.endianness='little'] - Byte order.
 * @param {number} [options.align=4] - Alignment in bytes.
 * @returns {Object} Field descriptor.
 */
export function Float32({ endianness, align }?: {
    endianness?: "little" | "big";
    align?: number;
}): any;
/**
 * Descriptor for a 64-bit float field.
 *
 * @param {Object} [options]
 * @param {'little'|'big'} [options.endianness='little'] - Byte order.
 * @param {number} [options.align=8] - Alignment in bytes.
 * @returns {Object} Field descriptor.
 */
export function Float64({ endianness, align }?: {
    endianness?: "little" | "big";
    align?: number;
}): any;
/**
 * Descriptor for a signed 64-bit integer field (BigInt).
 *
 * @param {Object} [options]
 * @param {'little'|'big'} [options.endianness='little'] - Byte order.
 * @param {number} [options.align=8] - Alignment in bytes.
 * @returns {Object} Field descriptor.
 */
export function BigInt64({ endianness, align }?: {
    endianness?: "little" | "big";
    align?: number;
}): any;
/**
 * Descriptor for an unsigned 64-bit integer field (BigInt).
 *
 * @param {Object} [options]
 * @param {'little'|'big'} [options.endianness='little'] - Byte order.
 * @param {number} [options.align=8] - Alignment in bytes.
 * @returns {Object} Field descriptor.
 */
export function BigUint64({ endianness, align }?: {
    endianness?: "little" | "big";
    align?: number;
}): any;
/**
 * Descriptor for an unsigned 8-bit integer field.
 *
 * @returns {Object} Field descriptor.
 */
export function Uint8(): any;
/**
 * Descriptor for a signed 8-bit integer field.
 *
 * @returns {Object} Field descriptor.
 */
export function Int8(): any;
/**
 * Descriptor for a nested buffer-backed object field.
 *
 * @param {Object<string, Object>} descriptors - Nested struct descriptor map.
 * @returns {Object} Field descriptor.
 */
export function NestedBufferBackedObject(descriptors: {
    [x: string]: any;
}): any;
/**
 * Descriptor for a nested array of buffer-backed objects.
 *
 * @param {number} length - Number of items.
 * @param {Object<string, Object>} descriptors - Nested struct descriptor map.
 * @returns {Object} Field descriptor.
 */
export function NestedArrayOfBufferBackedObjects(length: number, descriptors: {
    [x: string]: any;
}): any;
/**
 * Descriptor for a fixed-size UTF-8 string field.
 *
 * @param {number} maxBytes - Maximum byte length.
 * @returns {Object} Field descriptor.
 */
export function UTF8String(maxBytes: number): any;
/**
 * Descriptor for a reserved byte range (padding).
 *
 * @param {number} size - Byte length to reserve.
 * @returns {Object} Field descriptor.
 */
export function reserved(size: number): any;
